import numpy as np


def softmax(x, axis=-1):
    z = x - np.max(x, axis=axis, keepdims=True)  # shift so the largest exponent is exp(0) = 1
    e = np.exp(z)
    return e / np.sum(e, axis=axis, keepdims=True)

import numpy as np


def kmeans(X, init_centroids, n_iters):
    c = np.array(init_centroids, dtype=float)
    labels = np.zeros(len(X), dtype=int)
    for _ in range(n_iters):
        d = ((X[:, None, :] - c[None, :, :]) ** 2).sum(-1)  # (N, K) squared distances
        labels = d.argmin(axis=1)  # ties -> lower index
        for k in range(len(c)):
            mask = labels == k
            if mask.any():
                c[k] = X[mask].mean(axis=0)
    return c, labels

import numpy as np


def swiglu_ffn(x, w_gate, w_up, w_down):
    g = x @ w_gate
    return (g / (1 + np.exp(-g)) * (x @ w_up)) @ w_down  # silu(g) = g * sigmoid(g)

import numpy as np


def lora_linear(x, w, a, b, alpha, merge=False):
    scaling = alpha / a.shape[1]
    if merge:
        return w + scaling * (a @ b)
    return x @ w + scaling * ((x @ a) @ b)

import numpy as np


def beam_search(log_probs, start, eos, beam_size, max_len):
    v = log_probs.shape[1]
    beams, finished = [((), 0.0)], []
    for _ in range(max_len):
        cands = []
        for seq, score in beams:
            last = seq[-1] if seq else start
            for tok in range(v):
                cands.append((seq + (tok,), score + float(log_probs[last, tok])))
        cands.sort(key=lambda c: -c[1])
        beams = []
        for seq, score in cands[:beam_size]:
            (finished if seq[-1] == eos else beams).append((seq, score))
        if not beams:
            break
    seq, score = max(finished + beams, key=lambda c: c[1])
    return list(seq), score

