def bpe_train(text, num_merges):
    ids = list(text.encode("utf-8"))
    merges = []
    for i in range(num_merges):
        counts = {}
        for pair in zip(ids, ids[1:]):  # insertion order = first occurrence
            counts[pair] = counts.get(pair, 0) + 1
        if not counts:
            break
        best = max(counts, key=counts.get)  # ties -> earliest
        if counts[best] < 2:
            break
        new, out, j = 256 + i, [], 0
        while j < len(ids):
            if j < len(ids) - 1 and (ids[j], ids[j + 1]) == best:
                out.append(new)
                j += 2
            else:
                out.append(ids[j])
                j += 1
        ids = out
        merges.append(best)
    return merges

import numpy as np


def ppo_clip_loss(logp_new, logp_old, advantages, mask=None, clip_eps=0.2):
    if mask is None:
        mask = np.ones_like(logp_new)
    mask = mask.astype(float)
    ratio = np.exp(logp_new - logp_old)
    obj = np.minimum(ratio * advantages, np.clip(ratio, 1 - clip_eps, 1 + clip_eps) * advantages)
    loss = -(obj * mask).sum() / mask.sum()
    clip_frac = ((np.abs(ratio - 1) > clip_eps) * mask).sum() / mask.sum()
    return float(loss), float(clip_frac)

import numpy as np


def clip_loss(image_emb, text_emb, temperature=0.07):
    img = image_emb / np.linalg.norm(image_emb, axis=1, keepdims=True)
    txt = text_emb / np.linalg.norm(text_emb, axis=1, keepdims=True)
    logits = img @ txt.T / temperature

    def ce_diag(z):  # mean cross-entropy with targets on the diagonal
        z = z - z.max(axis=1, keepdims=True)
        logp = z - np.log(np.exp(z).sum(axis=1, keepdims=True))
        return -np.diag(logp).mean()

    return float((ce_diag(logits) + ce_diag(logits.T)) / 2)

import numpy as np


def speculative_accept(draft_tokens, draft_probs, target_probs, u):
    accepted = []
    for i, x in enumerate(draft_tokens):
        p, q = target_probs[i], draft_probs[i]
        if u[i] < min(1.0, p[x] / q[x]):
            accepted.append(int(x))
            continue
        residual = np.maximum(p - q, 0.0)
        return accepted, residual / residual.sum()
    return accepted, target_probs[len(draft_tokens)]
